<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="dark">
<title>Ubuntu Web Desktop — 24.04 LTS</title>
<style>
/* ============ base ============ */
:root{
  --accent:#e95420; --accent-soft:rgba(233,84,32,.32);
  --win:#2d2d32; --win-deep:#232327; --head:#34343a;
  --panel:#1d1d21; --line:rgba(255,255,255,.09);
  --text:#f2f2f4; --muted:#9a9aa4;
  --font:'Ubuntu','Cantarell','Segoe UI',system-ui,-apple-system,sans-serif;
  --mono:'Ubuntu Mono','Cascadia Mono','Consolas','Menlo',monospace;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden}
body{font-family:var(--font);font-size:14px;color:var(--text);background:#120a18;
  -webkit-user-select:none;user-select:none}
input,textarea{user-select:text;-webkit-user-select:text;font-family:inherit}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
::selection{background:rgba(233,84,32,.55);color:#fff}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:#4a4a53;border-radius:6px;border:2px solid transparent;background-clip:content-box}
::-webkit-scrollbar-thumb:hover{background:#5c5c66;background-clip:content-box}
::-webkit-scrollbar-track{background:transparent}
*{scrollbar-width:thin;scrollbar-color:#4a4a53 transparent}
:focus-visible{outline:2px solid var(--accent);outline-offset:1px}

/* ============ desktop root ============ */
#desktop{position:fixed;inset:0;overflow:hidden}
#desktop::before{content:'';position:absolute;inset:-25%;pointer-events:none;z-index:0;
  background:radial-gradient(640px 420px at 32% 30%,rgba(255,255,255,.055),transparent 70%);
  animation:drift 38s ease-in-out infinite alternate}
@keyframes drift{from{transform:translate(-4%,-3%)}to{transform:translate(6%,5%)}}
#mark{position:absolute;right:3.5vw;bottom:5vh;z-index:1;pointer-events:none;line-height:.9;text-align:right}
#mark b{display:block;font-size:min(17vw,210px);font-weight:800;letter-spacing:-.05em;color:rgba(255,255,255,.05)}
#mark span{font-size:min(2vw,20px);font-weight:300;letter-spacing:.55em;color:rgba(255,255,255,.14)}

/* desktop icons */
.desk-icons{position:absolute;left:88px;top:54px;display:flex;flex-direction:column;gap:6px;z-index:4}
.desk-icon{width:88px;padding:10px 6px;border-radius:10px;display:flex;flex-direction:column;align-items:center;gap:7px;border:1px solid transparent;cursor:default;transition:background .15s}
.desk-icon svg{width:42px;height:42px;filter:drop-shadow(0 4px 5px rgba(0,0,0,.45))}
.desk-icon span{font-size:11.5px;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,.9);text-align:center;line-height:1.25}
.desk-icon:hover{background:rgba(255,255,255,.10)}
.desk-icon.selected{background:var(--accent-soft);border-color:rgba(233,84,32,.55)}

/* ============ top bar ============ */
#topbar{position:absolute;top:0;left:0;right:0;height:32px;z-index:6000;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 8px;background:rgba(10,10,13,.86);backdrop-filter:blur(10px);border-bottom:1px solid rgba(255,255,255,.05)}
.tb-btn{display:flex;align-items:center;gap:8px;padding:4px 12px;border-radius:7px;font-size:12.5px;color:#e9e9ef;transition:background .15s}
.tb-btn:hover{background:rgba(255,255,255,.13)}
.tb-btn:active{background:rgba(255,255,255,.2)}
#tb-left{justify-self:start;display:flex;align-items:center;gap:4px}
#tb-right{justify-self:end}
#activities svg{width:16px;height:16px}
#clock{font-weight:500;letter-spacing:.02em;font-variant-numeric:tabular-nums}
#status svg{width:15px;height:15px;opacity:.95}
#status .pct{font-size:11.5px;color:#cfcfd8}

/* ============ dock / taskbar ============ */
#taskbar{position:absolute;left:10px;top:50%;transform:translateY(-50%);z-index:400;display:flex;flex-direction:column;gap:10px;padding:10px 9px;background:rgba(14,14,17,.58);backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.08);border-radius:18px;box-shadow:0 12px 34px rgba(0,0,0,.4)}
.launcher{width:52px;height:52px;border-radius:14px;display:grid;place-items:center;position:relative;background:linear-gradient(160deg,#3d3d45,#25252a);border:1px solid rgba(255,255,255,.07);transition:transform .16s cubic-bezier(.2,.9,.3,1.4),box-shadow .16s,background .16s}
.launcher svg{width:32px;height:32px}
.launcher:hover{transform:translateY(-3px) scale(1.06);box-shadow:0 10px 20px rgba(0,0,0,.45);background:linear-gradient(160deg,#47474f,#2b2b31)}
.launcher:active{transform:scale(.92)}
.launcher.running::before{content:'';position:absolute;left:-8px;top:50%;width:5px;height:5px;margin-top:-2.5px;border-radius:50%;background:#fff;box-shadow:0 0 7px rgba(255,255,255,.9)}
.launcher::after{content:attr(data-tip);position:absolute;left:calc(100% + 14px);top:50%;transform:translateY(-50%) translateX(-6px);background:#141419;border:1px solid var(--line);padding:5px 11px;border-radius:7px;font-size:12px;white-space:nowrap;opacity:0;pointer-events:none;transition:.16s;box-shadow:0 6px 18px rgba(0,0,0,.4)}
.launcher:hover::after{opacity:1;transform:translateY(-50%) translateX(0)}

/* ============ windows ============ */
.window{position:absolute;display:none;flex-direction:column;min-width:360px;min-height:240px;max-width:calc(100vw - 12px);max-height:calc(100vh - 40px);background:var(--win);border:1px solid rgba(255,255,255,.08);border-radius:11px;box-shadow:0 20px 55px rgba(0,0,0,.55),0 3px 10px rgba(0,0,0,.45);overflow:hidden;resize:both}
.window.focused{border-color:rgba(255,255,255,.14);box-shadow:0 28px 70px rgba(0,0,0,.65),0 4px 14px rgba(0,0,0,.5)}
.window.focused .titlebar{background:linear-gradient(#3b3b42,#313137)}
.win-in{animation:winIn .19s cubic-bezier(.2,.9,.3,1.18)}
@keyframes winIn{from{opacity:0;transform:scale(.955) translateY(10px)}to{opacity:1;transform:none}}
.titlebar{height:40px;flex:0 0 auto;display:flex;align-items:center;gap:8px;padding:0 9px 0 13px;background:linear-gradient(#333339,#2e2e33);border-bottom:1px solid rgba(0,0,0,.45);touch-action:none}
.tb-ico svg{width:17px;height:17px;display:block}
.win-title{flex:1;text-align:center;font-size:13px;font-weight:500;color:#e8e8ee;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;padding:0 6px}
.win-btn{width:26px;height:26px;flex:0 0 auto;border-radius:50%;display:grid;place-items:center;background:#4a4a53;color:#e6e6ec;font-size:14px;line-height:1;transition:background .14s,transform .14s}
.win-btn:hover{transform:scale(1.1)}
.win-btn:active{transform:scale(.94)}
.win-max{font-size:11px}
.win-max:hover{background:#5c5c66}
.win-close:hover{background:#e0483e;color:#fff}
.win-body{flex:1;display:flex;flex-direction:column;min-height:0}

/* ============ Files app ============ */
.files-bar{display:flex;align-items:center;gap:7px;padding:8px 10px;background:#2a2a2f;border-bottom:1px solid var(--line)}
.tbtn{width:31px;height:31px;flex:0 0 auto;border-radius:8px;display:grid;place-items:center;color:#d4d4dc;transition:background .14s}
.tbtn:hover{background:rgba(255,255,255,.09)}
.tbtn:active{background:rgba(255,255,255,.16)}
.tbtn:disabled{opacity:.28;pointer-events:none}
.tbtn svg{width:17px;height:17px}
#files-path{flex:1;min-width:60px;background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:7px 12px;font:12.5px var(--mono);color:#e8e8ee;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.crumb.link{color:#f09a72;cursor:pointer}
.crumb.link:hover{text-decoration:underline;color:#ffb894}
#files-filter{width:132px;flex:0 0 auto;background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:7px 11px;font-size:12.5px;color:var(--text);outline:none;transition:border-color .15s,width .2s}
#files-filter:focus{border-color:var(--accent);width:170px}
#files-filter::placeholder{color:#6d6d78}
#files-list{flex:1;overflow:auto;padding:6px;min-height:0;background:var(--win-deep)}
.fs-item{display:flex;align-items:center;gap:11px;padding:6px 10px;border-radius:8px;cursor:default;transition:background .12s}
.fs-item:hover{background:rgba(255,255,255,.055)}
.fs-item.selected{background:var(--accent-soft);box-shadow:inset 0 0 0 1px rgba(233,84,32,.5)}
.fs-ico svg{width:22px;height:22px;display:block}
.fs-name{flex:1;font-size:13.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fs-item.is-dir .fs-name{font-weight:600}
.fs-item::after{content:attr(data-size) "   ·   " attr(data-kind) "   ·   " attr(data-date);font:11.5px var(--mono);color:#84848f;white-space:pre;flex:0 0 auto;padding-left:12px}
.fs-empty{padding:38px;text-align:center;color:#77777f;font-size:13px;font-style:italic}
.statusbar{flex:0 0 auto;display:flex;justify-content:space-between;gap:12px;padding:5px 13px;font:11px var(--mono);color:#8b8b96;background:#26262b;border-top:1px solid var(--line);white-space:nowrap;overflow:hidden}

/* ============ Notepad app ============ */
#tabstrip{flex:0 0 auto;display:flex;align-items:flex-end;gap:6px;background:#232328;padding:8px 9px 0;border-bottom:1px solid #141417}
#tabs{display:flex;gap:4px;flex:1;min-width:0;overflow-x:auto;scrollbar-width:none}
#tabs::-webkit-scrollbar{display:none}
.tab{display:flex;align-items:center;gap:8px;padding:7px 8px 7px 13px;border-radius:9px 9px 0 0;background:#2b2b31;color:#b6b6c0;cursor:pointer;max-width:200px;flex:0 0 auto;border:1px solid transparent;border-bottom:0;transition:background .14s,color .14s}
.tab:hover{background:#34343b;color:#fff}
.tab.active{background:#1c1c20;color:#fff;box-shadow:inset 0 2px 0 var(--accent)}
.tab-label{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:148px}
.tab-close{width:18px;height:18px;flex:0 0 auto;border-radius:50%;display:grid;place-items:center;font-size:13px;line-height:1;color:#8b8b96;opacity:0;transition:.15s}
.tab:hover .tab-close,.tab.active .tab-close{opacity:1}
.tab-close:hover{background:#e0483e;color:#fff}
#new-tab{width:30px;height:30px;flex:0 0 auto;margin-bottom:3px;border-radius:9px;display:grid;place-items:center;font-size:19px;font-weight:300;color:#c9c9d2;transition:background .14s,transform .14s}
#new-tab:hover{background:var(--accent);color:#fff;transform:rotate(90deg)}
#editor{flex:1;min-height:0;width:100%;background:#1c1c20;color:#ededf2;border:0;outline:0;padding:15px 18px;font:13.5px/1.65 var(--mono);resize:none;tab-size:4}
#editor::placeholder{color:#585862}

/* ============ preview / about ============ */
.pv-meta{padding:11px 16px 9px;font:11.5px var(--mono);color:var(--muted);border-bottom:1px solid var(--line);background:var(--win-deep)}
#preview-body{flex:1;overflow:auto;margin:0;padding:14px 17px;font:12.5px/1.6 var(--mono);white-space:pre-wrap;word-break:break-word;background:var(--panel);color:#e6e6ec}
#preview-body.binary{display:grid;place-items:center;color:#8a8a95;font-style:italic;font-family:var(--font);font-size:13px}
.pv-actions{flex:0 0 auto;display:flex;justify-content:flex-end;gap:8px;padding:9px 12px;background:#26262b;border-top:1px solid var(--line)}
.btn{padding:7px 16px;border-radius:8px;background:#3a3a42;font-size:12.5px;transition:background .14s,transform .1s}
.btn:hover{background:#4a4a53}
.btn:active{transform:scale(.96)}
.btn.primary{background:var(--accent);color:#fff;font-weight:500}
.btn.primary:hover{background:#f26a3a}
.about-body{flex:1;overflow:auto;display:flex;flex-direction:column;align-items:center;gap:10px;padding:26px 26px 20px;text-align:center;background:radial-gradient(420px 260px at 50% -10%,rgba(233,84,32,.16),transparent 70%),var(--win-deep)}
.about-body svg{width:66px;height:66px;filter:drop-shadow(0 6px 14px rgba(233,84,32,.35))}
.about-body h1{font-size:21px;font-weight:300;letter-spacing:.01em}
.about-body h1 b{font-weight:700}
.about-tag{font-size:12px;color:var(--accent);letter-spacing:.28em;text-transform:uppercase;font-weight:500}
.about-body p{font-size:13px;color:#c8c8d1;line-height:1.6;max-width:340px}
.about-uname{font:11px var(--mono);color:#7f7f8a;background:#1a1a1e;border:1px solid var(--line);border-radius:7px;padding:6px 12px}

/* ============ popovers ============ */
.popover{position:absolute;z-index:7000;background:rgba(23,23,28,.97);border:1px solid var(--line);border-radius:14px;box-shadow:0 20px 55px rgba(0,0,0,.6);padding:14px;display:none}
.popover.show{display:block;animation:pop .17s cubic-bezier(.2,.9,.3,1.2)}
@keyframes pop{from{opacity:0;transform:scale(.95) translateY(-7px)}to{opacity:1;transform:none}}
#apps-pop{top:40px;left:8px;width:236px}
#apps-pop h3,#status-pop h3{font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:#7e7e89;margin:2px 2px 10px}
.app-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.app-tile{display:flex;flex-direction:column;align-items:center;gap:8px;padding:13px 6px;border-radius:11px;font-size:12.5px;color:#dcdce3;transition:background .14s,transform .14s}
.app-tile:hover{background:rgba(255,255,255,.09);transform:translateY(-2px)}
.app-tile svg{width:34px;height:34px}
#cal-pop{top:40px;left:50%;transform:translateX(-50%);width:284px}
#cal-pop.show{animation:popC .17s cubic-bezier(.2,.9,.3,1.2)}
@keyframes popC{from{opacity:0;transform:translateX(-50%) scale(.95) translateY(-7px)}to{opacity:1;transform:translateX(-50%)}}
.cal-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
#cal-title{font-size:13.5px;font-weight:500}
.cal-nav{width:26px;height:26px;border-radius:7px;display:grid;place-items:center;color:#cfcfd8;font-size:15px}
.cal-nav:hover{background:rgba(255,255,255,.1)}
#cal-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center}
